<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';security_headers();student_private_headers();$db=database();$student=student_account_current($db);if(!$student){header('Location: /aluno/login.php?next=%2Faluno%2Finventario.php',true,303);exit;}$studentId=(int)$student['id'];try{student_tool_require($db,$studentId,'lab_inventory');}catch(Throwable){http_response_code(403);exit('Ferramenta indisponível.');}$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!verify_csrf('student-inventory',$_POST['_csrf']??null))$error='Solicitação inválida.';else try{$action=(string)($_POST['action']??'create');if($action==='create')student_inventory_create($db,$studentId,$_POST);elseif($action==='move'){$amount=student_workbench_float($_POST['amount']??null);if($amount===null||$amount<=0)throw new RuntimeException('Informe uma quantidade válida.');$direction=(string)($_POST['direction']??'in');student_inventory_move($db,$studentId,(int)($_POST['item_id']??0),$direction==='out'?-$amount:$amount,$direction==='out'?'consume':'in',student_workspace_text($_POST['note']??'',500));}elseif($action==='archive')student_inventory_archive($db,$studentId,(int)($_POST['item_id']??0));else throw new RuntimeException('Ação inválida.');header('Location: /aluno/inventario.php?saved=1',true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}
}
$items=student_inventory_items($db,$studentId);$movements=student_inventory_movements($db,$studentId,0,40);student_shell_start('Inventário do laboratório',null,$student);?>
