<section class="student-section" data-student-local-key="inventory-history"><div class="student-section-heading"><div><p class="student-kicker">Histórico</p><h2 class="student-subtitle">Movimentações recentes</h2></div></div><?php if(!$movements):?><div class="student-empty">Nenhuma movimentação registrada.</div><?php else:?><div class="student-inventory-history"><?php foreach($movements as $movement):?><div><span><?=h((string)$movement['item_name'])?></span><strong class="<?=$movement['quantity_delta']<0?'is-out':'is-in'?>"><?=($movement['quantity_delta']>0?'+':'').h(student_workbench_number((float)$movement['quantity_delta'])).' '.h((string)$movement['unit'])?></strong><small><?=h((string)$movement['note'])?><?php if((int)($movement['test_id']??0)>0):?> · <a href="/aluno/teste.php?id=<?=(int)$movement['test_id']?>">abrir registro</a><?php endif;?></small></div><?php endforeach;?></div><?php endif;?></section><?php student_shell_end();
